import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.userData.handlers = {};
  const timelines = [];

  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    group.traverse(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const mat = obj.material;
        if (Array.isArray(mat)) {
          mat.forEach(m => m && m.dispose?.());
        } else if (mat && mat.dispose) {
          mat.dispose();
        }
      }
    });
  };

  const colors = {
    background: 0x0b0b10,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    textSecondary: 0x9fb0c4,
    rimLight: 0x99ccff,
  };

  // === PRISM GEOMETRY ===
  const prismGeometry = (() => {
    const sideLength = 1.2;
    const height = (Math.sqrt(3) / 2) * sideLength;
    const length = 1.8;
    const hl = length / 2;

    const positions = new Float32Array([
      // Front triangle
      0, height / 2, -hl,
      -sideLength / 2, -height / 2, -hl,
      sideLength / 2, -height / 2, -hl,
      // Back triangle
      0, height / 2, hl,
      -sideLength / 2, -height / 2, hl,
      sideLength / 2, -height / 2, hl,
    ]);

    const indices = new Uint32Array([
      // Front
      0, 2, 1,
      // Back
      3, 4, 5,
      // Bottom
      1, 2, 5, 1, 5, 4,
      // Left
      0, 4, 1, 0, 3, 4,
      // Right
      2, 3, 5, 2, 0, 3,
    ]);

    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geom.setIndex(new THREE.BufferAttribute(indices, 1));
    geom.computeVertexNormals();
    return geom;
  })();

  const prismMaterial = new THREE.MeshPhysicalMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new THREE.Color(colors.paper),
    attenuationDistance: 2.5,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    color: new THREE.Color(colors.paper),
  });

  const prism = new THREE.Mesh(prismGeometry, prismMaterial);
  prism.rotation.z = THREE.MathUtils.degToRad(12);
  prism.rotation.y = THREE.MathUtils.degToRad(20);
  group.add(prism);

  // === EMISSIVE CORE ===
  const coreGeometry = new THREE.OctahedronGeometry(0.35, 0);
  const coreMaterial = new THREE.MeshStandardMaterial({
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 2.2,
    metalness: 0,
    roughness: 0.2,
  });
  const core = new THREE.Mesh(coreGeometry, coreMaterial);
  prism.add(core);

  // === RIM LIGHT ===
  const rimLight = new THREE.DirectionalLight(colors.rimLight, 1.2);
  rimLight.position.set(-0.8, 0.2, -0.8);
  group.add(rimLight);

  // === CAUSTIC STREAK ===
  const causticTexture = (() => {
    const w = 256, h = 8;
    const data = new Uint8ClampedArray(w * h * 4);
    const stops = [
      { at: 0.0, r: 0x0b, g: 0x0b, b: 0x10 },
      { at: 0.2, r: 0xff, g: 0x2a, b: 0x38 },
      { at: 0.5, r: 0xe8, g: 0xec, b: 0xf2 },
      { at: 0.8, r: 0x9f, g: 0xb0, b: 0xc4 },
      { at: 1.0, r: 0x16, g: 0x16, b: 0x1d },
    ];

    for (let x = 0; x < w; x++) {
      const t = x / (w - 1);
      let r = stops[0].r, g = stops[0].g, b = stops[0].b;

      for (let i = 0; i < stops.length - 1; i++) {
        if (t >= stops[i].at && t <= stops[i + 1].at) {
          const s1 = stops[i], s2 = stops[i + 1];
          const range = s2.at - s1.at;
          const local = range > 0 ? (t - s1.at) / range : 0;
          r = Math.round(s1.r + (s2.r - s1.r) * local);
          g = Math.round(s1.g + (s2.g - s1.g) * local);
          b = Math.round(s1.b + (s2.b - s1.b) * local);
          break;
        }
      }

      for (let y = 0; y < h; y++) {
        const idx = (y * w + x) * 4;
        data[idx] = r;
        data[idx + 1] = g;
        data[idx + 2] = b;
        data[idx + 3] = 255;
      }
    }

    const tex = new THREE.DataTexture(data, w, h, THREE.RGBAFormat);
    tex.magFilter = THREE.LinearFilter;
    tex.minFilter = THREE.LinearFilter;
    tex.needsUpdate = true;
    return tex;
  })();

  const causticMaterial = new THREE.MeshBasicMaterial({
    map: causticTexture,
    transparent: true,
    opacity: 0.35,
    side: THREE.DoubleSide,
  });
  const causticGeometry = new THREE.PlaneGeometry(2.4, 0.5);
  const caustic = new THREE.Mesh(causticGeometry, causticMaterial);
  caustic.position.y = -1.1;
  caustic.rotation.x = Math.PI / 2;
  group.add(caustic);

  // === TEXT CONTENT ===
  if (ctx.fontAtlas) {
    const headlineText = ctx.fontAtlas.render
      ? ctx.fontAtlas.render({
          text: 'Light, machined.',
          family: 'Lora',
          size: 68,
          weight: 600,
          color: new THREE.Color(colors.paper),
          region: config.atlasRegion,
        })
      : null;

    if (headlineText) {
      headlineText.position.set(0, -1.75, 0.01);
      group.add(headlineText);
    }

    const captionText = ctx.fontAtlas.render
      ? ctx.fontAtlas.render({
          text: 'SAPPHIRE OVER DIAL / ZERO DISTORTION',
          family: 'JetBrains Mono',
          size: 18,
          weight: 400,
          color: new THREE.Color(colors.textSecondary),
          region: config.atlasRegion,
        })
      : null;

    if (captionText) {
      captionText.position.set(0, -2.25, 0.01);
      group.add(captionText);
    }
  }

  // === INTERACTION STATE ===
  const state = {
    rotX: 0,
    rotZ: THREE.MathUtils.degToRad(12),
    causticScaleX: 1.0,
  };

  const baseRotY = THREE.MathUtils.degToRad(20);
  const baseRotZ = THREE.MathUtils.degToRad(12);
  const maxDeg = 10;
  const maxRad = THREE.MathUtils.degToRad(maxDeg);
  let currentTimeline;

  // === HOVER HANDLERS ===
  group.userData.handlers.mousemove = (event) => {
    if (!event || event.clientX === undefined) return;

    const nx = event.clientX / window.innerWidth;
    const ny = event.clientY / window.innerHeight;

    const targetRotX = (ny - 0.5) * 2 * maxRad;
    const targetRotZ = baseRotZ + (nx - 0.5) * 2 * maxRad;
    const targetScale = 1.0 + (Math.abs(targetRotX) / maxRad) * 0.08;

    if (currentTimeline) currentTimeline.kill();

    currentTimeline = gsap.to(state, {
      rotX: targetRotX,
      rotZ: targetRotZ,
      causticScaleX: targetScale,
      duration: 0.35,
      ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
      onUpdate: () => {
        prism.rotation.x = state.rotX;
        prism.rotation.z = state.rotZ;
        caustic.scale.x = state.causticScaleX;
      },
    });
    timelines.push(currentTimeline);
  };

  group.userData.handlers.mouseleave = () => {
    if (currentTimeline) currentTimeline.kill();

    currentTimeline = gsap.to(state, {
      rotX: 0,
      rotZ: baseRotZ,
      causticScaleX: 1.0,
      duration: 0.9,
      ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
      onUpdate: () => {
        prism.rotation.x = state.rotX;
        prism.rotation.z = state.rotZ;
        caustic.scale.x = state.causticScaleX;
      },
    });
    timelines.push(currentTimeline);
  };

  // === APPLY CINEMATIC PRIMITIVES ===
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](prism, primitive.params || {});
      }
    });
  }

  return group;
}
